export default async function f({ recipient, report }, ctx) {
  let bytes = new TextEncoder().encode(report),
    s = "";
  for (const b of bytes) s += String.fromCharCode(b);
  const r = await ctx.actions.call("gmail.send_email", {
    to: recipient,
    subject: "Analysis of the documents provided",
    body: "The attached document contains the analysis of your uploaded files.",
    attachments: [{ filename: "analysis.txt", mimeType: "text/plain", contentBase64: btoa(s) }],
  });
  if (!r.messageId) throw Error("Inspect Gmail");
  return { messageId: r.messageId };
}

